components.draw:
const C = matmul(state.A, state.B), [r, c] = state.sel;
return [
  matrix(state.A, { id: 'A', label: 'A', highlightRows: [r] }),
  matrix(state.B, { id: 'B', label: 'B', op: '×', highlightCols: [c] }),
  matrix(C, { id: 'C', label: 'C', op: '=', highlightCells: [[r, c]] })
];

components.onClick:
if (part !== 'cell' || id !== 'C') return null;
const cols = state.B[0].length;
return { sel: [Math.floor(index / cols), index % cols] };
